      `TOTALS sheet=${sheet} by=uma claimed-total=30.00 due-total=2.00 overdue-total=0.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00 from=2026-03-05`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=3.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.00 due-total=3.00 overdue-total=0.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=5.00 from=2026-03-01 to=2026-03-09`,
