package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The rate set for each grade on a sheet. */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateChangeRepository changes;
    private final RateChain chain;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, RateChangeRepository changes, RateChain chain, SheetService sheets,
            RollupService rollup, Audit audit) {
        this.rates = rates;
        this.changes = changes;
        this.chain = chain;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The rates set on the sheet, by grade and then from-date (no from-date first). */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromAsc(sheetId);
    }

    /** The rates that apply on the sheet, its parent sheets' filling in for it (see {@link RateChain}). */
    @Transactional(readOnly = true)
    public List<Rate> applying(String sheetId) {
        return chain.applying(sheetId);
    }

    /**
     * Sets the grade's rate from the date (null: from the beginning of time) through the to-date (null: with no end),
     * replacing any rate it had for that from-date.
     */
    @Transactional
    public Rate set(String by, String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        LocalDate today = sheets.load(sheetId).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal scaled = pct.setScale(2, RoundingMode.UNNECESSARY);
        Rate rate = rates.findExact(sheetId, grade, from).orElseGet(() -> new Rate(sheetId, grade, from, scaled));
        rate.setPct(scaled);
        rate.setTo(to);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            // another user set this grade's rate for this from-date at the same moment
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That rate was just set by someone else.");
        }
        changes.saveAndFlush(new RateChange(saved, today));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + by + " grade=" + grade
                + " rate=" + saved.getPct().toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.session.SessionController;
import net.officefloor.hq.app.settings.ViewerPasses;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /**
     * A grade's rate as the screen shows it; the percent always carries two decimals, and the from-date is null for a
     * rate that applies from the beginning of time; the to-date is null for a rate with no end.
     */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to) {
        static RateView of(Rate r) {
            return new RateView(r.getGrade(), r.getPct().toPlainString(), r.getFrom(), r.getTo());
        }
    }

    /**
     * A rate as the form submits it: a percent of 0.00 or more with up to two decimals, an optional from-date and an
     * optional to-date not before it.
     */
    public record RateForm(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal pct,
            LocalDate from, LocalDate to) {

        @AssertTrue(message = "The to-date must not be before the from-date.")
        public boolean isToNotBeforeFrom() {
            return to == null || from == null || !to.isBefore(from);
        }
    }

    /** A candidate percent to preview: 0.00 or more with up to two decimals. */
    public record PreviewForm(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal pct) {
    }

    /** How many claims would show a different due, and the sum of the differences, with two decimals. */
    public record PreviewView(int count, String diff) {
    }

    private final RateService service;
    private final ClaimService claims;

    public RateController(RateService service, ClaimService claims) {
        this.service = service;
        this.claims = claims;
    }

    /** The rates set on the sheet, by grade and from-date; a grade with no rate is left out. */
    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.list(sheetId).stream().map(RateView::of).toList();
    }

    /**
     * The rates that apply on the sheet, by grade and from-date: its own, and for a date on which a grade has none in
     * force, its parent sheets' (see {@link RateChain}); a grade with no rate is left out.
     */
    @GetMapping("/applying")
    public List<RateView> applying(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.applying(sheetId).stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @Valid @RequestBody RateForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return RateView.of(service.set(user, sheetId, grade, form.from(), form.to(), form.pct()));
    }

    /** Previews the grade's rate at a candidate percent on every date; nothing is saved or audited, so a viewer may too. */
    @ViewerPasses
    @PostMapping("/{grade}/preview")
    public PreviewView preview(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @Valid @RequestBody PreviewForm form) {
        ClaimService.RatePreview p = claims.previewRate(sheetId, grade, form.pct());
        return new PreviewView(p.count(), p.diff().toPlainString());
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Adds a person for each pasted line of name,grade,terms,contact (the last two may be absent or blank), or updates the
 * person on the sheet the line names, all of them or none.
 */
@Service
public class PersonImportService {

    /** A pasted line read into the person form's fields. */
    private record Line(String name, String grade, Integer terms, String contact) {
    }

    /** What an import did: the people it added and the people it updated, each in line order. */
    public record Result(List<Person> added, List<Person> updated) {
    }

    private final PersonService people;
    private final PersonRepository repository;

    public PersonImportService(PersonService people, PersonRepository repository) {
        this.people = people;
        this.repository = repository;
    }

    /**
     * Reads every line first by the person form's rules, a name, person or contact repeated within the paste refused
     * too. Then, in line order, a line whose name is a name or alias of a person on the sheet (compared as names are)
     * updates that person as saving their edit would: the grade recorded from the sheet's today, and the terms and
     * contact set when the line gives them. Any other line adds a person as the form would. One change: any line
     * refused refuses them all, and nothing is stored or audited.
     */
    @Transactional
    public Result importPeople(String by, String sheetId, String text) {
        List<Line> lines = new ArrayList<>();
        List<Person> matches = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<Long> matched = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        int n = 0;
        for (String raw : text.split("\\r?\\n")) {
            n++;
            if (raw.isBlank()) {
                continue;
            }
            Line line = read(n, raw);
            if (!names.add(line.name().toLowerCase(Locale.ROOT))) {
                throw refused("Line " + n + " repeats the name " + line.name() + ".");
            }
            if (line.contact() != null && !contacts.add(line.contact())) {
                throw refused("Line " + n + " repeats the contact " + line.contact() + ".");
            }
            Person match = repository.findBySheetIdAndNameOrAlias(sheetId, line.name()).orElse(null);
            if (match != null && !matched.add(match.getId())) {
                throw refused("Line " + n + " repeats the person " + match.getName() + ".");
            }
            if (match == null && people.nameOrAliasInUse(sheetId, line.name())) {
                throw refused("Line " + n + ": the name " + line.name() + " is already in use on this sheet.");
            }
            if (line.contact() != null && (match == null
                    ? repository.existsBySheetIdAndContact(sheetId, line.contact())
                    : repository.existsBySheetIdAndContactAndIdNot(sheetId, line.contact(), match.getId()))) {
                throw refused("Line " + n + ": the contact " + line.contact() + " is already in use on this sheet.");
            }
            lines.add(line);
            matches.add(match);
        }
        if (lines.isEmpty()) {
            throw refused("Paste at least one line of name,grade,terms,contact.");
        }
        List<Person> added = new ArrayList<>();
        List<Person> updated = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            Line l = lines.get(i);
            Person match = matches.get(i);
            if (match == null) {
                added.add(people.add(by, sheetId, l.name(), l.grade(), l.terms(), l.contact()));
            } else {
                updated.add(people.update(by, sheetId, match.getId(), match.getVersion(), match.getName(), l.grade(),
                        null, l.terms() != null ? l.terms() : match.getTerms(),
                        l.contact() != null ? l.contact() : match.getContact()));
            }
        }
        return new Result(added, updated);
    }

    private Line read(int n, String raw) {
        String[] f = raw.split(",", 4);
        if (f.length < 2) {
            throw refused("Line " + n + " needs at least a name and a grade.");
        }
        String name = f[0].strip();
        if (name.isEmpty()) {
            throw refused("Line " + n + " has no name.");
        }
        if (name.length() > 200) {
            throw refused("Line " + n + " has a name longer than 200 characters.");
        }
        String grade = f[1].strip();
        if (!grade.matches("[ABC]")) {
            throw refused("Line " + n + " has a grade that is not A, B or C.");
        }
        Integer terms = null;
        String termsText = f.length > 2 ? f[2].strip() : "";
        if (!termsText.isEmpty()) {
            if (!termsText.matches("\\d{1,5}")) {
                throw refused("Line " + n + " has terms that are not a whole number of days.");
            }
            terms = Integer.valueOf(termsText);
        }
        String contact = f.length > 3 ? f[3].strip() : "";
        if (contact.length() > 200) {
            throw refused("Line " + n + " has a contact longer than 200 characters.");
        }
        return new Line(name, grade, terms, contact.isEmpty() ? null : contact.toLowerCase(Locale.ROOT));
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
    }
}
